function getStats(arr) {
  let min = arr[0], max = arr[0];
  for (const n of arr) {
    if (n < min) min = n;
    if (n > max) max = n;
  }
  return { min, max };
}
const stats = getStats([3, 1, 4, 1, 5]);
console.log(stats.min + ' ' + stats.max);
